#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long pot(long long a, long long b) {
    if (b == 0) return 1;
    long long c = pot(a, b / 2);
    c = c * c % MOD;
    return (b % 2 == 0) ? c : c * a % MOD;
}

int main() {
    long long n, m, k;
    cin >> n >> m >> k;

    if (k == -1 && (n % 2) != (m % 2))
        cout << 0;
    else
        cout << pot(pot(2, n - 1), m - 1);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long modPow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;

    while (exp > 0) {
        if (exp & 1LL) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1LL;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    cin >> n >> m >> k;

    if (k == -1 && (n % 2 != m % 2))
        cout << 0;
    else
        cout << modPow(modPow(2, n - 1), m - 1);

    return 0;
}

